T1: ① SELECT 도시, COUNT(*) FROM 고객 GROUP BY 도시;
T2: ② INSERT INTO 고객 (고객번호, 이름, 도시, 나이) VALUES (3, '김민재', '통영', 27);
T2: ③ COMMIT;
T1: ④ SELECT 나이, COUNT(*) FROM 고객 GROUP BY 나이;
T1: ⑤ COMMIT;
